async function panelApi(action,extra={},method='GET',body){const query=new URLSearchParams({action,...extra});return api('panel?'+query.toString(),method==='GET'?{}:{method,body:JSON.stringify(body||{})})}
function panelFmtBytes(value){const n=Number(value)||0;if(n>=1073741824)return (n/1073741824).toFixed(2)+' GB';if(n>=1048576)return (n/1048576).toFixed(1)+' MB';if(n>=1024)return (n/1024).toFixed(1)+' KB';return n+' B'}
function panelStateLabel(state){return state==='running'?'BERJALAN':state==='offline'?'MATI':state==='starting'?'MEMULAI':state==='stopping'?'BERHENTI':state==='installing'?'PEMASANGAN':'TIDAK DIKETAHUI'}
async function openPanelPage(){await loadPanelServers()}
async function loadPanelServers(){const box=$('panelServerList');try{const data=await panelApi('servers');panelState.servers=Array.isArray(data.servers)?data.servers:[];if(!panelState.servers.length){box.innerHTML='<p>Belum ada server panel aktif. Beli paket panel dulu di halaman <a href="#wallet">Saldo</a>.</p>';$('panelDetail').classList.add('hidden');return}box.innerHTML=panelState.servers.map(server=>`<div class="list-item"><span><b>${escapeHtml(server.name||server.serverName||'Server Panel')}</b><br><small>${escapeHtml(server.itemName||'Paket panel')} · ${escapeHtml(server.identifier)}<br>Dibuat ${escapeHtml(server.createdAt?new Date(server.createdAt).toLocaleString('id-ID'):'—')}</small></span><span><span class="chip ${server.state==='running'?'partner':'user'}">${panelStateLabel(server.state)}</span><br><button class="mini" type="button" data-open-server="${escapeHtml(server.identifier)}">KELOLA →</button></span></div>`).join('');box.querySelectorAll('[data-open-server]').forEach(button=>button.addEventListener('click',()=>selectPanelServer(button.dataset.openServer)))}catch(error){box.innerHTML=`<p>${escapeHtml(error.message)}</p>`}}
function selectPanelServer(identifier){panelState.current=panelState.servers.find(item=>item.identifier===identifier)||null;if(!panelState.current)return;$('panelDetail').classList.remove('hidden');$('panelServerName').textContent=panelState.current.name||panelState.current.serverName||'SERVER';$('panelOpenOriginal').href=`${panelState.current.panelUrl}/server/${identifier}`;panelState.dir='/';panelSwitchTab('console');refreshPanelResources();$('panelDetail').scrollIntoView({behavior:'smooth',block:'start'})}
function panelSwitchTab(tab){panelState.tab=tab;document.querySelectorAll('[data-ptab]').forEach(button=>button.classList.toggle('active',button.dataset.ptab===tab));$('panelTabConsole').classList.toggle('hidden',tab!=='console');$('panelTabFiles').classList.toggle('hidden',tab!=='files');$('panelTabStartup').classList.toggle('hidden',tab!=='startup');if(tab==='console')connectPanelConsole();if(tab==='files')loadPanelFiles();if(tab==='startup')loadPanelStartup()}
async function refreshPanelResources(){const id=panelState.current?.identifier;if(!id)return;try{const data=await panelApi('resources',{server:id});const r=data.resources||{};const state=data.state||'unknown';const pill=$('panelState');pill.textContent=panelStateLabel(state);const server=panelState.current;const limits=server.limits||{};const memoryLimit=limits.memory?panelFmtBytes(limits.memory*1048576):'∞';const diskLimit=limits.disk?panelFmtBytes(limits.disk*1048576):'∞';$('panelUsage').textContent=`Status server: ${panelStateLabel(state)} · CPU ${Number(r.cpu_absolute||0).toFixed(1)}% · RAM ${panelFmtBytes(r.memory_bytes)} / ${memoryLimit} · Disk ${panelFmtBytes(r.disk_bytes)} / ${diskLimit}`}catch{$('panelUsage').textContent='Penggunaan: server belum siap dibaca (mungkin masih pemasangan).'}}
function panelConsoleWrite(text){const log=$('panelConsoleLog');if(!log)return;log.textContent+=String(text??'');if(log.textContent.length>60000)log.textContent=log.textContent.slice(-60000);log.scrollTop=log.scrollHeight}
function panelConsoleClear(message){const log=$('panelConsoleLog');if(log)log.textContent=message||''}
async function connectPanelConsole(){const id=panelState.current?.identifier;if(!id)return;if(panelState.ws){try{panelState.ws.close()}catch{}panelState.ws=null}panelConsoleClear('Menghubungkan konsol…\n');try{const ticket=await panelApi('websocket',{server:id});if(!ticket.socket||!ticket.token)throw new Error('Tiket konsol kosong.');const ws=new WebSocket(ticket.socket);panelState.ws=ws;ws.onopen=()=>{ws.send(JSON.stringify({event:'auth',args:[ticket.token]}))};ws.onmessage=async event=>{let payload;try{payload=JSON.parse(event.data)}catch{return}const name=payload.event;const arg=Array.isArray(payload.args)?payload.args[0]:'';if(name==='auth success'){panelState.connected=true;panelConsoleWrite('[Konsol terhubung]\n');refreshPanelResources()}else if(name==='console output'||name==='install output'){panelConsoleWrite(String(arg||'')+'\n')}else if(name==='status'){panelConsoleWrite(`[Status: ${panelStateLabel(String(arg||''))}]\n`);refreshPanelResources()}else if(name==='token expiring'||name==='token expired'){try{const fresh=await panelApi('websocket',{server:id});if(panelState.ws===ws)ws.send(JSON.stringify({event:'auth',args:[fresh.token]}))}catch{}}};ws.onclose=()=>{if(panelState.ws===ws){panelState.connected=false;panelConsoleWrite('[Konsol terputus]\n')}};ws.onerror=()=>{panelConsoleWrite('[Konsol gagal tersambung — tekan tab Konsol lagi untuk mencoba ulang]\n')}}catch(error){panelConsoleWrite('[Gagal: '+error.message+']\n')}}
async function panelPower(signal,button){const id=panelState.current?.identifier;if(!id)return;busy(button,true);try{await panelApi('power',{server:id},'POST',{signal});toast(`Perintah ${signal} terkirim.`);panelConsoleWrite(`[Power: ${signal}]\n`);setTimeout(refreshPanelResources,1500);setTimeout(refreshPanelResources,4500)}catch(error){toast(error.message,true)}finally{busy(button,false)}}
function panelJoin(dir,name){return (dir==='/'?'':dir)+'/'+name}
async function loadPanelFiles(){const id=panelState.current?.identifier;if(!id)return;const box=$('panelFileList');$('panelDirPath').textContent=panelState.dir;$('panelEditor').classList.add('hidden');try{const data=await panelApi('files_list',{server:id,directory:panelState.dir});panelState.files=Array.isArray(data.files)?data.files:[];const rows=[...panelState.files].sort((a,b)=>(a.isFile===b.isFile?a.name.localeCompare(b.name):a.isFile?1:-1));box.innerHTML=rows.map(file=>`<div class="list-item"><span><b>${file.isFile?'📄':'📁'} ${escapeHtml(file.name)}</b><br><small>${file.isFile?panelFmtBytes(file.size):'Folder'}${file.modifiedAt?' · '+escapeHtml(new Date(file.modifiedAt).toLocaleString('id-ID')):''}</small></span><span class="panel-file-actions">${file.isFile?`<button class="mini" type="button" data-fedit="${escapeHtml(file.name)}">EDIT</button><button class="mini" type="button" data-fdown="${escapeHtml(file.name)}">UNDUH</button>`:`<button class="mini" type="button" data-fopen="${escapeHtml(file.name)}">BUKA</button>`}${!file.isFile||/\.(zip|tar|tar\.gz|tgz)$/i.test(file.name)?`<button class="mini" type="button" data-fextract="${escapeHtml(file.name)}">EKSTRAK</button>`:''}<button class="mini" type="button" data-frename="${escapeHtml(file.name)}">NAMA</button><button class="mini" type="button" data-fdelete="${escapeHtml(file.name)}">HAPUS</button></span></div>`).join('')||'<p>Folder ini kosong.</p>';box.querySelectorAll('[data-fopen]').forEach(b=>b.addEventListener('click',()=>{panelState.dir=panelJoin(panelState.dir,b.dataset.fopen);loadPanelFiles()}));box.querySelectorAll('[data-fedit]').forEach(b=>b.addEventListener('click',()=>openPanelEditor(b.dataset.fedit)));box.querySelectorAll('[data-fdown]').forEach(b=>b.addEventListener('click',()=>downloadPanelFile(b.dataset.fdown)));box.querySelectorAll('[data-fextract]').forEach(b=>b.addEventListener('click',()=>extractPanelFile(b.dataset.fextract)));box.querySelectorAll('[data-frename]').forEach(b=>b.addEventListener('click',()=>renamePanelFile(b.dataset.frename)));box.querySelectorAll('[data-fdelete]').forEach(b=>b.addEventListener('click',()=>deletePanelFile(b.dataset.fdelete)))}catch(error){box.innerHTML=`<p>${escapeHtml(error.message)}</p>`}}
async function openPanelEditor(name){const id=panelState.current?.identifier;const file=panelJoin(panelState.dir,name);try{const data=await panelApi('files_contents',{server:id,file});panelState.editing=data.file;$('panelEditorName').textContent=data.file;$('panelEditorText').value=data.content;$('panelEditor').classList.remove('hidden');$('panelEditor').scrollIntoView({behavior:'smooth'})}catch(error){toast(error.message,true)}}
async function savePanelEditor(button){if(!panelState.editing)return;const id=panelState.current.identifier;busy(button,true);try{await panelApi('files_save',{server:id},'POST',{file:panelState.editing,content:$('panelEditorText').value});toast('File tersimpan.');loadPanelFiles()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function downloadPanelFile(name){const id=panelState.current.identifier;try{const data=await panelApi('files_download',{server:id,file:panelJoin(panelState.dir,name)});if(data.url)window.open(data.url,'_blank','noopener');else toast('URL unduhan kosong.',true)}catch(error){toast(error.message,true)}}
async function extractPanelFile(name){const id=panelState.current.identifier;try{await panelApi('files_decompress',{server:id},'POST',{root:panelState.dir,file:name});toast('Arsip diekstrak.');loadPanelFiles()}catch(error){toast(error.message,true)}}
async function renamePanelFile(name){const to=prompt('Nama baru untuk '+name,name);if(!to||to===name)return;const id=panelState.current.identifier;try{await panelApi('files_rename',{server:id},'POST',{root:panelState.dir,from:name,to});toast('Nama diganti.');loadPanelFiles()}catch(error){toast(error.message,true)}}
async function deletePanelFile(name){if(!confirm('Hapus '+name+'? Tindakan ini tidak bisa dibatalkan.'))return;const id=panelState.current.identifier;try{await panelApi('files_delete',{server:id},'POST',{root:panelState.dir,files:[name]});toast('Terhapus.');loadPanelFiles()}catch(error){toast(error.message,true)}}
async function uploadPanelFile(fileInput){const file=fileInput.files?.[0];fileInput.value='';if(!file)return;const id=panelState.current.identifier;try{const data=await panelApi('files_upload_url',{server:id});if(!data.url)throw new Error('URL unggah kosong.');const form=new FormData();form.append('files',file);const response=await fetch(data.url,{method:'POST',body:form});if(!response.ok)throw new Error('Unggah gagal (HTTP '+response.status+').');toast('File terunggah.');loadPanelFiles()}catch(error){toast(error.message+' Unggah langsung mungkin dibatasi panel; alternatifnya buat file lewat tombol ＋ FILE.',true)}}
async function loadPanelStartup(){const id=panelState.current?.identifier;if(!id)return;const box=$('panelStartupVars');try{const data=await panelApi('startup',{server:id});$('panelStartupCommand').value=data.startupCommand||'';$('panelDockerImage').value=data.dockerImage||'';const vars=Array.isArray(data.variables)?data.variables:[];box.innerHTML=vars.map(v=>`<div class="list-item"><span><b>${escapeHtml(v.key)}</b><br><small>${escapeHtml(v.description||v.name||'')}</small></span><span class="panel-var-edit"><input type="text" value="${escapeHtml(v.value)}" data-var-input="${escapeHtml(v.key)}" ${v.editable?'':'disabled'}><button class="mini" type="button" data-var-save="${escapeHtml(v.key)}" ${v.editable?'':'disabled'}>SIMPAN</button></span></div>`).join('')||'<p>Tidak ada variable startup.</p>';box.querySelectorAll('[data-var-save]').forEach(b=>b.addEventListener('click',async()=>{const key=b.dataset.varSave;const input=box.querySelector(`[data-var-input="${key}"]`);busy(b,true);try{await panelApi('startup_variable',{server:id},'POST',{key,value:input.value});toast(`Variable ${key} disimpan. Restart server untuk menerapkan.`)}catch(error){toast(error.message,true)}finally{busy(b,false)}}))}catch(error){box.innerHTML=`<p>${escapeHtml(error.message)}</p>`}}
async function submitWalletTopup(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),amount=Number(form.elements.amount.value);if(!Number.isInteger(amount))return toast('Nominal top up tidak valid.',true);busy(button,true,'MEMBUAT INVOICE…');try{const result=await post('wallet/topup',{amount});toast(state.wallet?.mode==='manual_dana'?'Permintaan top up dikirim. Menunggu verifikasi owner.':'Invoice DANA dibuat. Selesaikan pembayaran untuk menambah saldo.');await loadWallet();$('walletActiveInvoice').scrollIntoView({behavior:'smooth',block:'center'})}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function sessionAction(event){const button=event.target.closest('[data-action]');if(!button)return;const id=button.dataset.id;if(button.dataset.action==='new'){location.hash='connect';return}if(button.dataset.action==='settings'){state.selected=id;location.hash='settings';return}if(button.dataset.action==='restart'){busy(button,true);try{await post('session/restart',{session_id:id});toast('Restart dikirim.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}if(button.dataset.action==='remove'&&confirm(`Hapus session +${id}?`)){busy(button,true);try{await post('session/logout',{session_id:id});toast('Session dihapus.');await loadSessions()}catch(error){toast(error.message,true)}finally{busy(button,false)}}}
async function requestPairing(event){event.preventDefault();const phone=$('pairPhone').value.replace(/\D/g,'');if(phone.length<8)return toast('Nomor WhatsApp tidak valid.',true);const button=event.currentTarget.querySelector('button');const copy=$('copyPairCode');$('pairCode').textContent='••••-••••';delete $('pairCode').dataset.code;copy.disabled=true;state.pairLogs=[];addPairLog('Meminta kode pairing dari server.');busy(button,true,'MEMINTA KODE...');try{const data=await post('session/pairing',{phone});const formatted=formatPairCode(data.code||data.pairingCode);$('pairCode').textContent=formatted.display;$('pairCode').dataset.code=formatted.code;copy.disabled=!formatted.code;$('pairStatus').textContent=data.message||'Kode dibuat. Masukkan di WhatsApp.';addPairLog(formatted.code?'Kode pairing diterima. Gunakan tombol Salin Code atau salin dari layar.':'Server belum mengirim kode pairing.');state.selected=phone;let lastStatus='';clearInterval(state.pairTimer);state.pairTimer=setInterval(async()=>{try{const status=await api(`session/status?session_id=${encodeURIComponent(phone)}`);const current=String(status.status||'pending');$('pairStatus').textContent=`Status: ${current}`;if(current!==lastStatus){lastStatus=current;addPairLog(`Status session: ${current}.`)}if(current==='connected'){clearInterval(state.pairTimer);addPairLog('WhatsApp berhasil terhubung.');toast('Bot berhasil terhubung.');location.hash='dashboard'}}catch{if(lastStatus!=='check_failed'){lastStatus='check_failed';addPairLog('Status session belum dapat diperiksa; mencoba lagi otomatis.')}}},4000)}catch(error){toast(error.message,true);$('pairStatus').textContent=error.message;addPairLog(`Pairing gagal: ${error.message||'kesalahan tidak diketahui'}.`)}finally{busy(button,false)}}
async function openSettings(){await loadSessions();if(!state.sessions.length){location.hash='connect';return}sessionOptions($('settingsSession'));if(!state.selected||!state.sessions.some(item=>String(item.sessionId)===String(state.selected)))state.selected=String(state.sessions[0].sessionId);$('settingsSession').value=state.selected;await loadSettings()}
async function loadSettings(){state.selected=$('settingsSession').value;if(!state.selected)return;const item=state.sessions.find(x=>String(x.sessionId)===String(state.selected));$('sessionStatus').textContent=item?`${String(item.status).toUpperCase()} · +${item.sessionId}`:'—';const data=await api(`settings/get?session_id=${encodeURIComponent(state.selected)}`),s=data.settings||{},f=$('settingsForm').elements;f.bot_name.value=s.bot_name||'';f.owner_number.value=s.owner_number||'';$('lockedOwnerNumber').value=s.locked_owner_number||'6287813709432';f.prefix.value=s.prefix||'.';f.mode.value=['self','private'].includes(s.mode)?'self':'public';f.only_group.checked=s.only_group===true;f.registration_required.checked=s.registration_required!==false;f.default_limit.value=s.default_limit??25;f.auto_typing.checked=s.auto_typing!==false;f.auto_translate.checked=s.auto_translate!==false;f.send_music.checked=s.tiktok?.sendMusic!==false;f.menu_audio_enabled.checked=s.menu_audio_enabled!==false;f.max_photos.value=s.tiktok?.maxPhotos||8;f.website_url.value=s.links?.websiteUrl||'';f.channel_url.value=s.links?.channelUrl||'';f.upch_channel_url.value=s.upch_channel?.url||'';f.group_url.value=s.links?.groupUrl||'';f.typing_min.value=s.auto_typing_config?.minDelayMs??s.autoTyping?.minDelayMs??0;f.typing_max.value=s.auto_typing_config?.maxDelayMs??s.autoTyping?.maxDelayMs??80;f.typing_cps.value=s.auto_typing_config?.charsPerSecond??s.autoTyping?.charsPerSecond??10000;f.translate_language.value=s.auto_translate_config?.defaultLanguage??s.autoTranslate?.defaultLanguage??'id';f.connect_timeout.value=s.runtime?.connectTimeoutMs??60000;f.keepalive.value=s.runtime?.keepAliveIntervalMs??30000;f.retry_delay.value=s.runtime?.retryRequestDelayMs??250;f.max_retries.value=s.runtime?.maxMessageRetries??5;f.multiplier.value=s.multiplier??38;f.wait_text.value=s.wait_text||'';f.error_text.value=s.error_text||'';f.disabled_plugins.value=(s.disabled_plugins||[]).join('\n');await loadBackups()}
async function saveSettings(event){event.preventDefault();if(!state.selected)return;const f=event.currentTarget.elements,links={};if(f.website_url.value.trim())links.websiteUrl=f.website_url.value.trim();if(f.channel_url.value.trim())links.channelUrl=f.channel_url.value.trim();if(f.group_url.value.trim())links.groupUrl=f.group_url.value.trim();const payload={session_id:state.selected,upch_channel_url:f.upch_channel_url.value.trim(),bot_name:f.bot_name.value.trim(),owner_number:f.owner_number.value.replace(/\D/g,''),prefix:f.prefix.value,mode:f.mode.value,only_group:f.only_group.checked,registration_required:f.registration_required.checked,default_limit:Number(f.default_limit.value),auto_typing:f.auto_typing.checked,auto_typing_config:{minDelayMs:Number(f.typing_min.value),maxDelayMs:Number(f.typing_max.value),charsPerSecond:Number(f.typing_cps.value),includeMedia:true},auto_translate:f.auto_translate.checked,auto_translate_config:{source:'id',defaultLanguage:f.translate_language.value.trim()||'id'},menu_audio_enabled:f.menu_audio_enabled.checked,runtime:{connectTimeoutMs:Number(f.connect_timeout.value),keepAliveIntervalMs:Number(f.keepalive.value),retryRequestDelayMs:Number(f.retry_delay.value),maxMessageRetries:Number(f.max_retries.value)},wait_text:f.wait_text.value,error_text:f.error_text.value,multiplier:Number(f.multiplier.value),tiktok:{sendMusic:f.send_music.checked,maxPhotos:Number(f.max_photos.value)},links,disabled_plugins:f.disabled_plugins.value.split(/\n/).map(x=>x.trim()).filter(Boolean)};const button=event.currentTarget.querySelector('[type="submit"]');busy(button,true,'MENYIMPAN...');try{await post('settings/apply',payload);toast('Settings tersimpan dan diterapkan.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function loadBackups(){if(!state.selected)return;const data=await api(`backup/list?session_id=${encodeURIComponent(state.selected)}`);$('backupList').innerHTML=(data.backups||[]).map(item=>`<div class="list-item"><span><b>${escapeHtml(new Date(item.createdAt).toLocaleString('id-ID'))}</b><br><small>${escapeHtml(item.id)}</small></span><button class="mini" data-restore="${escapeHtml(item.id)}">RESTORE</button></div>`).join('')||'<p>Belum ada backup.</p>'}
async function backupAction(event){const button=event.target.closest('[data-restore]');if(!button||!confirm('Restore backup ini?'))return;busy(button,true);try{await post('backup/restore',{session_id:state.selected,backup_id:button.dataset.restore});toast('Backup dipulihkan.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}
function populateFeedbackSessions(){const select=$('feedbackSession'),previous=select.value;select.innerHTML='<option value="">Pilih session bot</option>'+state.sessions.map(item=>`<option value="${escapeHtml(item.sessionId)}">+${escapeHtml(item.sessionId)} · ${escapeHtml(String(item.status||'unknown').toUpperCase())}</option>`).join('');if(state.sessions.some(item=>String(item.sessionId)===String(previous)))select.value=previous;else if(state.selected&&state.sessions.some(item=>String(item.sessionId)===String(state.selected)))select.value=String(state.selected)}
function feedbackTargetChanged(){const bot=$('feedbackTarget').value==='bot';$('feedbackSessionWrap').classList.toggle('hidden',!bot);if(bot&&!state.sessions.length){$('feedbackStatus').textContent='Belum ada session bot yang dapat dipilih.';$('feedbackStatus').classList.remove('hidden')}}
function renderFeedback(rows=[]){const list=$('feedbackList');list.innerHTML=rows.map(row=>{const meta=row.metadata&&typeof row.metadata==='object'?row.metadata:{};const isBot=meta.source==='bot';const target=meta.target==='bot'?`BOT +${meta.session_id||'\u2014'}`:meta.target==='bot-main'?'BOT UTAMA':'WEBSITE';const targetChip=meta.target==='bot'?'partner':'user';const title=escapeHtml(meta.title||'Laporan bug');const description=escapeHtml(meta.description||'');const steps=meta.steps?`<div class="feedback-steps"><b>LANGKAH</b><br>${escapeHtml(meta.steps)}</div>`:'';const plugin=meta.plugin?`<div class="feedback-steps"><b>PLUGIN</b><br>${escapeHtml(meta.plugin)}${meta.command?` \u00b7 ${escapeHtml(meta.command)}`:''}${Number(meta.occurrences)>1?` \u00b7 terjadi ${Number(meta.occurrences)}\u00d7`:''}</div>`:'';const date=escapeHtml(new Date(row.created_at).toLocaleString('id-ID'));return`<article class="feedback-item"><div class="feedback-meta"><span class="chip ${targetChip}">${target}</span><span class="chip owner">${escapeHtml(String(meta.status||'open').toUpperCase())}</span>${isBot?`<span class="chip">\u{1F916} OTOMATIS</span>`:''}<time>${date}</time></div><h4>${title}</h4><p>${description}</p>${plugin}${steps}</article>`}).join('')||'<p>Belum ada laporan feedback.</p>'}async function loadFeedback(){const data=await api('platform/feedback');renderFeedback(data.feedback||[])}
async function openFeedback(){await loadSessions();populateFeedbackSessions();feedbackTargetChanged();await loadFeedback()}
async function submitFeedback(event){event.preventDefault();const form=event.currentTarget,target=form.elements.target.value,sessionId=$('feedbackSession').value;if(target==='bot'&&!sessionId)return toast('Pilih session bot yang mengalami masalah.',true);const button=form.querySelector('[type="submit"]'),status=$('feedbackStatus');busy(button,true,'MENGIRIM...');status.textContent='Mengirim laporan pribadi ke owner platform...';status.classList.remove('hidden');try{await post('platform/feedback',{target,session_id:target==='bot'?sessionId:'',title:form.elements.title.value.trim(),description:form.elements.description.value.trim(),steps:form.elements.steps.value.trim(),page:'feedback'});form.elements.title.value='';form.elements.description.value='';form.elements.steps.value='';form.elements.target.value='website';feedbackTargetChanged();status.textContent='Feedback berhasil dikirim. Terima kasih.';toast('Feedback berhasil dikirim.');await loadFeedback()}catch(error){status.textContent=error.message;toast(error.message,true)}finally{busy(button,false)}}
async function loadChat(){const data=await api('platform/chat?limit=150'),box=$('chatMessages'),near=box.scrollHeight-box.scrollTop-box.clientHeight<100;box.innerHTML=(data.messages||[]).map(message=>`<article class="message ${message.auth_id===state.profile?.id?'mine':''}"><div class="message-meta"><b>${escapeHtml(message.display_name||'User')}</b>${chips(message.roles)}<time>${escapeHtml(new Date(message.created_at).toLocaleString('id-ID'))}</time>${hasRole('owner')||hasRole('admin')?`<button class="delete-message" data-delete-message="${escapeHtml(message.id)}">×</button>`:''}</div><p>${escapeHtml(message.body)}</p></article>`).join('')||'<p>Belum ada pesan.</p>';if(near)box.scrollTop=box.scrollHeight}
async function openChat(){await loadChat();state.chatTimer=setInterval(()=>loadChat().catch(()=>{}),5000)}
async function chatAction(event){const button=event.target.closest('[data-delete-message]');if(!button||!confirm('Hapus pesan ini?'))return;try{await api(`platform/chat/${button.dataset.deleteMessage}`,{method:'DELETE'});await loadChat()}catch(error){toast(error.message,true)}}
async function sendChat(event){event.preventDefault();const body=$('chatInput').value.trim();if(!body)return;const button=event.currentTarget.querySelector('button');busy(button,true,'KIRIM...');try{await post('platform/chat',{body});$('chatInput').value='';await loadChat()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function openPlugins(){await loadSessions();sessionOptions($('pluginSession'));await loadPlugins()}
async function loadPlugins(){const data=await api('platform/plugins');$('pluginList').innerHTML=(data.plugins||[]).map(plugin=>`<article class="plugin-card"><div class="section-head"><h3>${escapeHtml(plugin.slug)}</h3>${hasRole('owner')?`<button class="mini danger" data-plugin-delete="${escapeHtml(plugin.id)}">HAPUS</button>`:''}</div><p>${escapeHtml(plugin.description||'Tanpa deskripsi.')}</p><small>${escapeHtml(plugin.filename)} · ${escapeHtml(plugin.uploader_email||'')}</small><div class="actions"><button class="mini" data-plugin-copy="${escapeHtml(plugin.id)}">SALIN</button><button class="mini" data-plugin-download="${escapeHtml(plugin.id)}">DOWNLOAD</button><button class="mini" data-plugin-install="${escapeHtml(plugin.id)}">INSTALL</button></div></article>`).join('')||'<p>Belum ada plugin di katalog.</p>'}
async function pluginAction(event){const button=event.target.closest('[data-plugin-copy],[data-plugin-download],[data-plugin-install],[data-plugin-delete]');if(!button)return;try{if(button.dataset.pluginCopy||button.dataset.pluginDownload){const id=button.dataset.pluginCopy||button.dataset.pluginDownload,item=(await api(`platform/plugins/${id}`)).plugin;if(button.dataset.pluginCopy){await navigator.clipboard.writeText(item.code);toast('Code disalin.')}else{const url=URL.createObjectURL(new Blob([item.code],{type:'text/javascript'})),link=document.createElement('a');link.href=url;link.download=item.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}if(button.dataset.pluginInstall){const sessionId=$('pluginSession').value;if(!sessionId)throw new Error('Pilih session.');if(confirm(`Install plugin ke +${sessionId}?`)){await post(`platform/plugins/${button.dataset.pluginInstall}/install`,{session_id:sessionId});toast('Plugin terinstal.')}}if(button.dataset.pluginDelete&&confirm('Hapus plugin dari katalog?')){await api(`platform/plugins/${button.dataset.pluginDelete}`,{method:'DELETE'});await loadPlugins()}}catch(error){toast(error.message,true)}}
async function uploadPlugin(event){event.preventDefault();const form=event.currentTarget,file=form.elements.file.files[0],button=form.querySelector('button');if(!file)return;if(file.size>512*1024)return toast('Plugin maksimal 512 KB.',true);busy(button,true,'MENGIRIM...');try{const data=await post('platform/plugins',{slug:form.elements.slug.value,filename:file.name,description:form.elements.description.value,code:await file.text()});toast(data.warnings?.length?`Plugin masuk dengan ${data.warnings.length} peringatan.`:'Plugin masuk katalog.');form.reset();await loadPlugins()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function openConsole(){await loadSessions();sessionOptions($('consoleSession'));if(state.sessions.length){$('consoleSession').value=String(state.sessions[0].sessionId);await loadLogs()}state.logTimer=setInterval(()=>loadLogs().catch(()=>{}),5000)}
async function loadLogs(){const id=$('consoleSession').value;if(!id){$('consoleLogs').textContent='Pilih session.';return}const data=await api(`console/logs?session_id=${encodeURIComponent(id)}&limit=250`);$('consoleLogs').textContent=(data.logs||[]).map(item=>`[${new Date(item.t).toLocaleTimeString('id-ID')}] [${String(item.level||'info').toUpperCase()}] ${item.text||''}`).join('\n')||'Belum ada log.'}
async function runConsole(event){event.preventDefault();const session_id=$('consoleSession').value,command=$('consoleCommand').value.trim(),button=event.currentTarget.querySelector('button');if(!session_id||!command)return;busy(button,true,'RUN...');try{const data=await post('console/run',{session_id,command});$('consoleOutput').textContent=JSON.stringify(data.output,null,2);$('consoleCommand').value='';await loadLogs()}catch(error){$('consoleOutput').textContent=error.message;toast(error.message,true)}finally{busy(button,false)}}
function mainConnectionLabel(status={}){if(status.connected)return 'TERHUBUNG';if(status.pairing_active)return 'MENUNGGU PAIRING';if(status.registered)return 'TERDAFTAR / MENYAMBUNG';return 'BELUM TERPASANG'}
function renderMainPairCode(){const output=$('mainBotPairCode'),copy=$('copyMainBotPairCode');if(!output||!copy)return;const formatted=formatPairCode(state.mainPairCode);output.textContent=formatted.display;output.dataset.code=formatted.code;copy.disabled=!formatted.code}
function detectMainPairCode(){const source=state.mainConsoleOutput.slice(Math.max(0,state.mainPairingSearchOffset));const matches=[...source.matchAll(/PAIRING\s+CODE\s*:\s*([a-z0-9-]{4,40})/gi)];const value=matches.at(-1)?.[1]||'';if(!value)return;const formatted=formatPairCode(value);if(formatted.code){state.mainPairCode=formatted.code;renderMainPairCode();$('mainBotPairingStatus').textContent='Pairing code siap disalin.'}}
function renderMainConsole(){const box=$('mainConsoleLogs');if(!box)return;box.textContent=state.mainConsoleOutput||'Belum ada output console.';box.scrollTop=box.scrollHeight;detectMainPairCode()}
async function loadMainConsoleLogs(){if(!hasRole('owner'))return;const data=await api(`platform/main-console/logs?cursor=${encodeURIComponent(state.mainConsoleCursor)}`);if(data.reset){state.mainConsoleOutput='';state.mainPairingSearchOffset=0}for(const chunk of Array.isArray(data.chunks)?data.chunks:[])state.mainConsoleOutput+=String(chunk?.text||'');if(state.mainConsoleOutput.length>700000){const excess=state.mainConsoleOutput.length-700000;state.mainConsoleOutput=state.mainConsoleOutput.slice(excess);state.mainPairingSearchOffset=Math.max(0,state.mainPairingSearchOffset-excess)}state.mainConsoleCursor=Math.max(state.mainConsoleCursor,Number(data.cursor)||0);renderMainConsole()}
async function loadMainConsole(){if(!hasRole('owner'))return;const box=$('mainConsoleStatus');box.textContent='Memeriksa status bot utama…';const data=await api('platform/main-console/status');const status=data.status||{},ready=Boolean(status.console_prompt_active),enabled=Boolean(status.main_bot_enabled),pairButton=$('requestMainBotPairing'),numberInput=$('mainBotNumber');box.innerHTML=`<b>${escapeHtml(mainConnectionLabel(status))}</b><br><small>Bot utama: ${escapeHtml(String(enabled?'AKTIF':'NONAKTIF'))} · Socket: ${escapeHtml(String(status.socket_ready?'siap':'belum siap'))} · Prompt console: ${escapeHtml(String(ready?'aktif':'tidak aktif'))} · Runtime: ${escapeHtml(String(status.uptime_seconds||0))} dtk</small>`;applyMainBotToggle(status);applyAutoreadToggle(status);if(numberInput)numberInput.disabled=false;if(pairButton)pairButton.disabled=false;const info=status.pairing_number_set?`Nomor tersimpan: ${status.pairing_number_masked}.`:'Belum ada nomor tersimpan.';if(!enabled)$('mainBotPairingStatus').textContent=`Bot utama NONAKTIF. ${info} Simpan nomor untuk mengaktifkan sekaligus meminta pairing code.`;else if(!state.mainPairCode)$('mainBotPairingStatus').textContent=`${info} Bot akan memakai nomor ini saat menyambung; kode muncul otomatis di log.`}
async function openMainConsole(){state.mainConsoleCursor=0;state.mainConsoleOutput='';state.mainPairingSearchOffset=0;renderMainPairCode();renderMainConsole();await loadMainConsole();await loadMainConsoleLogs();clearInterval(state.mainConsoleTimer);state.mainConsoleTimer=setInterval(()=>{loadMainConsoleLogs().catch(()=>{})},1500)}
async function submitMainConsoleInput(event){event.preventDefault();const form=event.currentTarget,input=$('mainConsoleInput').value,button=form.querySelector('button');if(!input)return;busy(button,true,'MENGIRIM...');try{await post('platform/main-console/input',{input});$('mainConsoleInput').value='';await loadMainConsoleLogs()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function submitMainBotPairing(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');let number=$('mainBotNumber').value.replace(/\D/g,'');if(number.startsWith('0'))number=`62${number.slice(1)}`;else if(number.startsWith('8'))number=`62${number}`;if(number.length<8||number.length>15)return toast('Nomor bot utama tidak valid.',true);busy(button,true,'MENGIRIM...');state.mainPairCode='';state.mainPairingSearchOffset=state.mainConsoleOutput.length;renderMainPairCode();$('mainBotPairingStatus').textContent='Nomor disimpan di server bot. Menunggu pairing code…';try{await post('platform/main-console/pairing-number',{number});$('mainBotNumber').value='';await loadMainConsoleLogs()}catch(error){$('mainBotPairingStatus').textContent=error.message;toast(error.message,true)}finally{busy(button,false)}}
async function copyMainBotPairCode(){const code=$('mainBotPairCode')?.dataset.code||'';if(!code)return toast('Belum ada pairing code untuk disalin.',true);try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(code);else{const area=document.createElement('textarea');area.value=code;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();if(!document.execCommand('copy'))throw new Error('copy failed');area.remove()}$('mainBotPairingStatus').textContent='Pairing code disalin ke clipboard.';toast('Pairing code disalin.')}catch{toast('Tidak dapat menyalin otomatis. Salin dari layar.',true)}}
function clearMainConsole(){state.mainConsoleOutput='';state.mainPairingSearchOffset=0;renderMainConsole()}
function roleSelect(user){return`<select multiple size="5" data-role-id="${escapeHtml(user.id)}" ${user.locked?'disabled':''}>${['user','admin','partner','owner','developer'].map(role=>`<option value="${role}" ${(user.roles||[]).includes(role)?'selected':''}>${role}</option>`).join('')}</select>`}
async function loadOwner(){if(!hasRole('owner'))return;const[data,audit]=await Promise.all([api('platform/admin/users'),api('platform/audit')]);$('ownerUsers').textContent=data.totals?.users??0;$('ownerOnline').textContent=data.totals?.online??0;$('ownerSessions').textContent=data.totals?.sessions??0;$('ownerTable').innerHTML=(data.users||[]).map(user=>`<tr data-search="${escapeHtml(`${user.username||''} ${user.email||''}`.toLowerCase())}"><td><b>${escapeHtml(user.username||'Tanpa username')}</b><br><span>${escapeHtml(user.email||'')}</span>${user.locked?'<br><span class="chip owner">LOCKED</span>':''}</td><td>${roleSelect(user)}</td><td>${(user.sessions||[]).map(session=>`<div>+${escapeHtml(session.sessionId)} ${escapeHtml(session.status)}</div>`).join('')||'—'}</td><td>${user.banned?'<span class="chip owner">BANNED</span>':'<span class="chip user">ACTIVE</span>'}</td><td>${user.locked?'—':`<div class="actions"><button class="mini" data-user-save="${escapeHtml(user.id)}">SAVE</button><button class="mini" data-user-ban="${escapeHtml(user.id)}" data-banned="${Boolean(user.banned)}">${user.banned?'UNBAN':'BAN'}</button><button class="mini danger" data-user-delete="${escapeHtml(user.id)}">HAPUS</button></div>`}</td></tr>`).join('');renderAudit(audit.logs||[]);filterOwner();await loadPanelAutoOrder()}
function defaultPanelPackages(){return[{id:'starter-1',name:'Starter 1 GB',description:'Paket awal',price:0,memoryMb:1024,cpuPercent:40,diskMb:1024,enabled:false},{id:'starter-2',name:'Starter 2 GB',description:'Paket awal',price:0,memoryMb:2048,cpuPercent:70,diskMb:2048,enabled:false},{id:'starter-4',name:'Starter 4 GB',description:'Paket awal',price:0,memoryMb:4096,cpuPercent:120,diskMb:4096,enabled:false}]}
function panelPackageCard(item={}){const value=(key,fallback='')=>escapeHtml(item[key]??fallback);return`<article class="panel" data-panel-package><div class="section-head"><h4>PAKET</h4><button class="mini danger" type="button" data-panel-package-remove>HAPUS</button></div><div class="form-grid"><label>ID Paket<input data-panel-field="id" maxlength="40" required pattern="[a-z0-9-]+" value="${value('id')}"></label><label>Nama Paket<input data-panel-field="name" maxlength="80" required value="${value('name')}"></label><label>Harga (Rp)<input data-panel-field="price" type="number" min="0" max="100000000" step="1" required value="${value('price',0)}"></label><label>RAM (MB)<input data-panel-field="memoryMb" type="number" min="128" max="1048576" step="1" required value="${value('memoryMb',1024)}"></label><label>CPU (%)<input data-panel-field="cpuPercent" type="number" min="1" max="100000" step="1" required value="${value('cpuPercent',40)}"></label><label>Disk (MB)<input data-panel-field="diskMb" type="number" min="128" max="10485760" step="1" required value="${value('diskMb',1024)}"></label></div><label>Deskripsi<textarea data-panel-field="description" maxlength="240">${value('description')}</textarea></label><label><input data-panel-field="enabled" type="checkbox" ${item.enabled?'checked':''}> Aktifkan paket ini untuk checkout</label></article>`}
function renderPanelPackages(packages){const editor=$('panelPackageEditor');const values=Array.isArray(packages)&&packages.length?packages:defaultPanelPackages();editor.innerHTML=values.map(panelPackageCard).join('')}
function currentPanelPackages(){return[...$('panelPackageEditor').querySelectorAll('[data-panel-package]')].map(card=>{const field=name=>card.querySelector(`[data-panel-field="${name}"]`);return{id:field('id').value.trim().toLowerCase(),name:field('name').value.trim(),description:field('description').value.trim(),price:Number(field('price').value),memoryMb:Number(field('memoryMb').value),cpuPercent:Number(field('cpuPercent').value),diskMb:Number(field('diskMb').value),enabled:field('enabled').checked}})}
function panelStatusText(data){const p=data||{},panel=p.pltaConfigured?'PLTA siap':'PLTA belum diisi',bridge=p.pltcConfigured?'Bridge PLTC siap':'Bridge PLTC belum diisi',payment=p.payment?.configured?(p.payment?.mode==='manual_dana'?'DANA manual siap · verifikasi owner':'TriPay DANA siap'):(p.payment?.mode==='manual_dana'?'DANA manual belum siap':'TriPay DANA belum diisi'),checkout=p.checkoutReady?'Checkout dapat dilanjutkan ke tahap provisioning.':'Checkout belum aktif.';return`${panel} · ${bridge} · ${payment}. ${checkout}`}
async function loadPanelAutoOrder(){if(!hasRole('owner'))return;const status=$('panelAutoOrderStatus');status.textContent='Memeriksa konfigurasi Panel Auto Order…';try{const data=await api('platform/panel/status');state.panelAutoOrder=data;status.textContent=panelStatusText(data);$('panelAutoOrderForm').elements.panel_url.value=data.panelUrl||'';$('panelAutoOrderForm').elements.site_url.value=data.siteUrl||location.origin;$('panelAutoOrderForm').elements.payment_mode.value=data.payment?.mode||'manual_dana';$('panelAutoOrderForm').elements.tripay_channel.value=data.payment?.channel||'DANA';$('panelAutoOrderForm').elements.clear_plta.checked=false;$('panelAutoOrderForm').elements.clear_pltc.checked=false;$('panelAutoOrderForm').elements.clear_tripay.checked=false;{const f=$('panelAutoOrderForm').elements;if(f.egg_id)f.egg_id.value=data.provisioning?.eggId||'';if(f.location_id)f.location_id.value=data.provisioning?.locationId||'';if(f.docker_image)f.docker_image.value=data.provisioning?.dockerImage||'';if(f.startup)f.startup.value=data.provisioning?.startup||''}renderPanelPackages(data.packages);renderPanelProductsSummary(data.products)}catch(error){status.textContent=`Konfigurasi Panel belum dapat dimuat: ${error.message}`;renderPanelPackages(state.panelAutoOrder?.packages)}await loadManualTopups().catch(error=>{$('manualTopupRequests').textContent=`Permintaan top up belum dapat dimuat: ${error.message}`})}
async function savePanelAutoOrder(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),payload={panelUrl:form.elements.panel_url.value.trim(),siteUrl:form.elements.site_url.value.trim(),paymentMode:form.elements.payment_mode.value,tripayChannel:form.elements.tripay_channel.value.trim().toUpperCase(),clearPlta:form.elements.clear_plta.checked,clearPltc:form.elements.clear_pltc.checked,clearTripay:form.elements.clear_tripay.checked,provisioning:{eggId:Number(form.elements.egg_id?.value||0),locationId:Number(form.elements.location_id?.value||0),dockerImage:(form.elements.docker_image?.value||'').trim(),startup:(form.elements.startup?.value||'').trim()}};const mapped=[['plta','plta'],['pltc','pltc'],['tripay_merchant_code','tripayMerchantCode'],['tripay_api_key','tripayApiKey'],['tripay_private_key','tripayPrivateKey']];for(const[from,to]of mapped){const value=form.elements[from].value.trim();if(value)payload[to]=value}busy(button,true,'MENYIMPAN…');try{const data=await post('platform/panel/settings',payload);state.panelAutoOrder=data;form.elements.plta.value='';form.elements.pltc.value='';form.elements.tripay_merchant_code.value='';form.elements.tripay_api_key.value='';form.elements.tripay_private_key.value='';form.elements.clear_plta.checked=false;form.elements.clear_pltc.checked=false;form.elements.clear_tripay.checked=false;$('panelAutoOrderStatus').textContent=panelStatusText(data);toast('Konfigurasi Panel disimpan terenkripsi.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function testPanelAutoOrder(){const button=$('testPanelConnection');busy(button,true,'MENGUJI…');try{const data=await post('platform/panel/test-connection',{});toast(`Panel terhubung. PLTA: ${data.pterodactyl?'OK':'—'} · Bridge: ${data.bridge?'OK':'belum diisi'}`);await loadPanelAutoOrder()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function savePanelPackages(event){event.preventDefault();const button=event.currentTarget.querySelector('[type="submit"]'),packages=currentPanelPackages();busy(button,true,'MENYIMPAN…');try{const data=await post('platform/panel/packages',{packages});state.panelAutoOrder=data;renderPanelPackages(data.packages);$('panelAutoOrderStatus').textContent=panelStatusText(data);toast('Katalog paket tersimpan.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}
function addPanelPackage(){const packages=currentPanelPackages();packages.push({id:`paket-${packages.length+1}`,name:'Paket Baru',description:'',price:0,memoryMb:1024,cpuPercent:40,diskMb:1024,enabled:false});renderPanelPackages(packages)}
function panelPackageAction(event){const remove=event.target.closest('[data-panel-package-remove]');if(!remove)return;const cards=$('panelPackageEditor').querySelectorAll('[data-panel-package]');if(cards.length<=1)return toast('Minimal satu paket diperlukan.',true);remove.closest('[data-panel-package]').remove()}
async function savePanelProducts(event){event.preventDefault();const btn=event.currentTarget.querySelector('[type="submit"]');let products;try{products=JSON.parse($('panelProductsJson').value||'[]')}catch{return toast('JSON produk tidak valid.',true)}if(!Array.isArray(products))return toast('Katalog produk harus berupa array JSON.',true);busy(btn,true,'MENYIMPAN…');try{const data=await post('platform/panel/settings',{products});state.panelAutoOrder=data;renderPanelProductsSummary(data.products);toast('Katalog produk disimpan.')}catch(error){toast(error.message,true)}finally{busy(btn,false)}}
function renderPanelProductsSummary(products=[]){const el=$('panelProductsSummary');if(!el)return;el.innerHTML=(products||[]).length?products.map(p=>`<div class="list-item"><span><b>${escapeHtml(p.name)}</b><br><small>${escapeHtml(p.type)}${p.type==='premium'?` · ${escapeHtml(p.days)} hari`:` · stok ${escapeHtml(p.inStock??0)}`} · ${escapeHtml(p.id)}</small></span><div class="actions"><b>${formatIdr(p.price)}</b><span class="chip ${p.enabled?'user':''}">${p.enabled?'AKTIF':'NONAKTIF'}</span></div></div>`).join(''):'<p>Belum ada produk.</p>'}
function renderManualTopups(topups=[]){$('manualTopupRequests').innerHTML=topups.map(item=>`<div class="list-item"><span><b>${escapeHtml(formatIdr(item.amount))}</b><br><small>${escapeHtml(item.createdAt?new Date(item.createdAt).toLocaleString('id-ID'):'—')} · ${escapeHtml(item.merchantRef||item.id)}</small></span><div class="actions"><button class="mini" data-manual-topup="${escapeHtml(item.id)}" data-manual-decision="approve">SETUJUI</button><button class="mini danger" data-manual-topup="${escapeHtml(item.id)}" data-manual-decision="reject">TOLAK</button></div></div>`).join('')||'<p>Tidak ada permintaan top up yang menunggu verifikasi.</p>'}
async function loadManualTopups(){if(!hasRole('owner'))return;const data=await api('platform/panel/manual-topups');renderManualTopups(data.topups||[])}
async function manualTopupAction(event){const button=event.target.closest('[data-manual-topup]');if(!button)return;const decision=button.dataset.manualDecision,id=button.dataset.manualTopup;if(!confirm(`${decision==='approve'?'Setujui':'Tolak'} permintaan top up ini? Pastikan pembayaran DANA sudah diperiksa.`))return;busy(button,true);try{await post('platform/panel/manual-topups/review',{id,decision});toast(decision==='approve'?'Saldo pengguna berhasil ditambahkan.':'Permintaan top up ditolak.');await loadManualTopups()}catch(error){toast(error.message,true)}finally{busy(button,false)}}

function renderAudit(logs){$('auditList').innerHTML=logs.map(log=>{const feedback=log.action==='feedback.submit'&&log.metadata&&typeof log.metadata==='object'?`<br><small><b>${escapeHtml(log.metadata.title||'Feedback')}</b><br>${escapeHtml(log.metadata.description||'')}</small>`:'';return`<div class="list-item"><span><b>${escapeHtml(log.action)}</b> · ${escapeHtml(log.actor_email)}<br><small>${escapeHtml(log.target||'')}</small>${feedback}</span><time>${escapeHtml(new Date(log.created_at).toLocaleString('id-ID'))}</time></div>`}).join('')||'<p>Belum ada audit log.</p>'}
function filterOwner() {const q=$('ownerSearch').value.trim().toLowerCase();$('ownerTable').querySelectorAll('tr[data-search]').forEach(row=>row.classList.toggle('hidden',Boolean(q&&!row.dataset.search.includes(q))))}
async function ownerAction(event){const save=event.target.closest('[data-user-save]'),ban=event.target.closest('[data-user-ban]'),del=event.target.closest('[data-user-delete]');try{if(save){const select=document.querySelector(`[data-role-id="${CSS.escape(save.dataset.userSave)}"]`);await api(`platform/admin/users/${save.dataset.userSave}/roles`,{method:'PATCH',body:JSON.stringify({roles:[...select.selectedOptions].map(x=>x.value)})});toast('Role diperbarui.')}if(ban){await api(`platform/admin/users/${ban.dataset.userBan}/ban`,{method:'PATCH',body:JSON.stringify({banned:ban.dataset.banned!=='true'})});toast('Status diperbarui.')}if(del&&confirm('Hapus akun permanen?')){await api(`platform/admin/users/${del.dataset.userDelete}`,{method:'DELETE'});toast('Akun dihapus.')}if(save||ban||del)await loadOwner()}catch(error){toast(error.message,true)}}
async function createAccount(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');busy(button,true,'MEMBUAT...');try{await post('platform/admin/users',{username:form.elements.username.value,email:form.elements.email.value,password:form.elements.password.value,roles:[...form.elements.roles.selectedOptions].map(x=>x.value)});form.reset();toast('Akun dibuat.');await loadOwner()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function applyMedia(event){event.preventDefault();if(!state.selected)return toast('Pilih session dahulu.',true);const file=$('mediaFile').files[0],url=$('mediaUrl').value.trim(),kind=$('mediaKind').value,button=event.currentTarget.querySelector('button');if(!file&&!url)return toast('Masukkan URL atau file.',true);busy(button,true,'MENGUNGGAH...');$('mediaProgress').classList.remove('hidden');try{let payload={session_id:state.selected,kind,url};if(file){const max=file.type.startsWith('video/')?15*1024*1024:8*1024*1024;if(file.size>max)throw new Error(`File maksimal ${max/1024/1024} MB.`);const signed=await post('platform/media/sign',{session_id:state.selected,kind,mime_type:file.type});$('mediaProgress').textContent='Mengunggah file...';const{error}=await state.storage.storage.from('umi-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:true});if(error)throw error;payload={session_id:state.selected,kind,storage_path:signed.path,mime_type:file.type,size_bytes:file.size}}$('mediaProgress').textContent='Menerapkan media...';await post('platform/media/apply',payload);$('mediaProgress').textContent='Media berhasil diterapkan.';$('mediaFile').value='';$('mediaUrl').value='';toast('Media bot diperbarui.')}catch(error){$('mediaProgress').textContent=error.message;toast(error.message,true)}finally{busy(button,false)}}
function appendAgentMessage(role,text){const box=$('agentMessages'),item=document.createElement('article');item.className=`message ${role==='user'?'mine':''}`;const p=document.createElement('p');p.textContent=String(text||'');item.append(p);box.append(item);box.scrollTop=box.scrollHeight}
async function loadAgent(){const owner=hasRole('owner'),data=await api(owner?'platform/agent/status':'agent/status');const status=$('agentStatus');status.textContent=data.configured?'SIAP':'BUTUH API KEY';status.className=`chip ${data.configured?'partner':'owner'}`;$('agentIntro').textContent=owner?'Mode owner aktif: Agent dapat memantau bot dan memakai tool server yang dijaga policy. Untuk API key dan terminal, buka AI Owner.':'Agent bantuan untuk website dan Jadibot. Workspace publik dipisahkan dari server dan tidak memiliki akses shell.'}
async function sendAgent(event){event.preventDefault();const input=$('agentInput'),button=event.currentTarget.querySelector('button'),prompt=input.value.trim();if(!prompt)return;appendAgentMessage('user',prompt);input.value='';busy(button,true,'BERPIKIR…');try{const data=await post(hasRole('owner')?'platform/agent/chat':'agent/chat',{prompt});appendAgentMessage('assistant',data.answer||'Agent tidak mengirim jawaban.')}catch(error){appendAgentMessage('assistant',`Error: ${error.message}`)}finally{busy(button,false)}}
async function loadOwnerAgent(){const data=await api('platform/agent/status'),notice=$('ownerAgentStatus'),health=data.health||{},monitor=`Monitor · Bot utama: ${health.mainBotConnected?'online':'offline'} · Jadibot: ${Number(health.jadibotConnected)||0} online · Memori: ${Number(health.memoryMb)||0} MB`;notice.textContent=data.configured?`Agent siap · Provider: ${data.provider||'groq'} · Model: ${data.model||'openai/gpt-oss-120b'} · ${monitor}`:`AI belum dikonfigurasi. ${monitor}`;const form=$('agentSettingsForm');form.elements.provider.value=data.provider||'groq';form.elements.model.value=data.model||'openai/gpt-oss-120b'}
async function loadProfile(){
  /* Pastikan profile terbaru dari server */
  try { await hydrateIdentity() } catch {}
  const u=state.profile||state.session?.user||{};
  const el=id=>document.getElementById(id);
  if(el('profileUsername'))el('profileUsername').value=u.username||u.user_metadata?.username||'—';
  if(el('profileEmail'))el('profileEmail').value=u.email||'—';
  if(el('profileRole'))el('profileRole').textContent=(u.roles||[u.role||'user']).join(', ')||'user';
  if(el('profileJoined'))el('profileJoined').textContent=u.created_at?new Date(u.created_at).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):'—';
  /* Avatar / inisial */
  const avatarEl=el('profileAvatar');
  if(avatarEl){const name=u.username||u.email||'?';avatarEl.textContent=name.charAt(0).toUpperCase()}
  const dn=el('profileDisplayName');if(dn)dn.textContent=u.username||u.user_metadata?.username||u.email||'—';
  const dr=el('profileDisplayRole');if(dr)dr.textContent=(u.roles||[]).join(', ')||'user';
  /* Token */
  let apiToken=u.api_token||'';
  let tokenVisible=false;
  const tokenEl=el('profileToken'),toggleBtn=el('toggleTokenBtn'),copyBtn=el('copyTokenBtn'),regenBtn=el('regenerateTokenBtn');
  if(tokenEl)tokenEl.textContent=apiToken?'••••••••••••••••':'Belum ada token. Klik REGENERATE.';
  if(toggleBtn){toggleBtn.onclick=()=>{if(!apiToken)return toast('Belum ada token. Klik REGENERATE dahulu.',true);tokenVisible=!tokenVisible;if(tokenEl)tokenEl.textContent=tokenVisible?apiToken:'••••••••••••••••';toggleBtn.textContent=tokenVisible?'SEMBUNYIKAN':'TAMPILKAN'};}
  if(copyBtn){copyBtn.onclick=()=>{if(!apiToken)return toast('Belum ada token.',true);navigator.clipboard.writeText(apiToken).then(()=>toast('Token tersalin!')).catch(()=>toast('Gagal menyalin',true));};}
  if(regenBtn){regenBtn.onclick=async()=>{if(!confirm('Regenerate token? Token lama akan tidak berlaku.'))return;try{const d=await post('platform/auth/token');if(d.token){apiToken=d.token;if(state.profile)state.profile.api_token=d.token;tokenVisible=false;if(tokenEl)tokenEl.textContent='••••••••••••••••';if(toggleBtn)toggleBtn.textContent='TAMPILKAN';toast('Token baru dibuat!')}else toast(d.error||'Gagal',true)}catch(e){toast(e.message,true)}};}
  /* Password */
  const pwForm=el('changePasswordForm');
  if(pwForm&&!pwForm._bound){pwForm._bound=true;pwForm.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const d=await post('platform/auth/change-password',{old_password:f.elements.old_password.value,new_password:f.elements.new_password.value});if(d.ok){f.reset();toast('Password berhasil diubah!')}else toast(d.error||'Gagal',true)}catch(err){toast(err.message,true)}};}
}
